export const contourWgsl = "// Marching squares. Each cell of the grid and each level appends up to two line segments.\n// The rules are the same as in MarchingSquares.cs, so that both find the same segments.\n\nstruct Params {\n    level_count: u32,\n    capacity: u32,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n@group(0) @binding(1) var values: texture_2d<f32>;\n@group(0) @binding(2) var<storage, read> levels: array<f32>;\n@group(0) @binding(3) var<storage, read_write> segments: array<vec2f>;\n@group(0) @binding(4) var<storage, read_write> counter: atomic<u32>;\n\n// The point that interrupts a line, PolylineStyle.Gap.\nconst gap = vec2f(1e30, 1e30);\n\nfn is_nan(value: f32) -> bool {\n    return (bitcast<u32>(value) & 0x7fffffffu) > 0x7f800000u;\n}\n\nfn append(start: vec2f, end: vec2f) {\n    let index = atomicAdd(&counter, 1u);\n    if index < params.capacity {\n        segments[index * 3u] = start;\n        segments[index * 3u + 1u] = end;\n        segments[index * 3u + 2u] = gap;\n    }\n}\n\nfn crossing(first: f32, second: f32, level: f32) -> f32 {\n    return (level - first) / (second - first);\n}\n\n// The crossing of an edge: 0 bottom, 1 right, 2 top, 3 left.\nfn edge_point(edge: i32, cell: vec2f, a: f32, b: f32, c: f32, d: f32, level: f32) -> vec2f {\n    switch edge {\n        case 0: { return cell + vec2f(crossing(a, b, level), 0.0); }\n        case 1: { return cell + vec2f(1.0, crossing(b, c, level)); }\n        case 2: { return cell + vec2f(crossing(d, c, level), 1.0); }\n        default: { return cell + vec2f(0.0, crossing(a, d, level)); }\n    }\n}\n\nfn append_edges(first: i32, second: i32, cell: vec2f, a: f32, b: f32, c: f32, d: f32, level: f32) {\n    append(edge_point(first, cell, a, b, c, d, level), edge_point(second, cell, a, b, c, d, level));\n}\n\nfn march(cell: vec2f, a: f32, b: f32, c: f32, d: f32, level: f32) {\n    var mask = 0u;\n    if a >= level { mask |= 1u; }\n    if b >= level { mask |= 2u; }\n    if c >= level { mask |= 4u; }\n    if d >= level { mask |= 8u; }\n\n    switch mask {\n        case 1u, 14u: { append_edges(3, 0, cell, a, b, c, d, level); }\n        case 2u, 13u: { append_edges(0, 1, cell, a, b, c, d, level); }\n        case 3u, 12u: { append_edges(3, 1, cell, a, b, c, d, level); }\n        case 4u, 11u: { append_edges(1, 2, cell, a, b, c, d, level); }\n        case 6u, 9u: { append_edges(0, 2, cell, a, b, c, d, level); }\n        case 7u, 8u: { append_edges(3, 2, cell, a, b, c, d, level); }\n        case 5u, 10u: {\n            // Two opposite corners: the middle decides which of them are connected.\n            let center_is_high = (a + b + c + d) / 4.0 >= level;\n            if (mask == 5u) == center_is_high {\n                append_edges(0, 1, cell, a, b, c, d, level);\n                append_edges(2, 3, cell, a, b, c, d, level);\n            } else {\n                append_edges(3, 0, cell, a, b, c, d, level);\n                append_edges(1, 2, cell, a, b, c, d, level);\n            }\n        }\n        default: { }\n    }\n}\n\n@compute @workgroup_size(16, 16)\nfn main(@builtin(global_invocation_id) id: vec3u) {\n    let size = textureDimensions(values);\n    if id.x + 1u >= size.x || id.y + 1u >= size.y {\n        return;\n    }\n\n    let position = vec2i(id.xy);\n    let a = textureLoad(values, position, 0).r;\n    let b = textureLoad(values, position + vec2i(1, 0), 0).r;\n    let c = textureLoad(values, position + vec2i(1, 1), 0).r;\n    let d = textureLoad(values, position + vec2i(0, 1), 0).r;\n    if is_nan(a) || is_nan(b) || is_nan(c) || is_nan(d) {\n        return;\n    }\n\n    for (var i = 0u; i < params.level_count; i++) {\n        march(vec2f(id.xy), a, b, c, d, levels[i]);\n    }\n}\n";

export const densityWgsl = "// Counts points per pixel. bin_points runs once per block of points, resolve turns the counts into a\n// texture of values and finds the highest one.\n\nstruct Params {\n    scale: vec2f,\n    offset: vec2f,\n    size: vec2u,\n    count: u32,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n@group(0) @binding(1) var<storage, read> points: array<vec2f>;\n@group(0) @binding(2) var<storage, read_write> bins: array<atomic<u32>>;\n@group(0) @binding(3) var target_texture: texture_storage_2d<r32float, write>;\n@group(0) @binding(4) var<storage, read_write> maximum: atomic<u32>;\n\n// A dimension of a dispatch is limited to 65535 groups, so large clouds run in rows of groups.\nconst groups_per_row = 1024u;\nconst points_per_group = 256u;\n\n@compute @workgroup_size(256)\nfn bin_points(@builtin(global_invocation_id) id: vec3u) {\n    let index = id.y * groups_per_row * points_per_group + id.x;\n    if index >= params.count {\n        return;\n    }\n\n    let pixel = points[index] * params.scale + params.offset;\n    if pixel.x >= 0.0 && pixel.y >= 0.0 && pixel.x < f32(params.size.x) && pixel.y < f32(params.size.y) {\n        atomicAdd(&bins[u32(pixel.y) * params.size.x + u32(pixel.x)], 1u);\n    }\n}\n\n@compute @workgroup_size(16, 16)\nfn resolve(@builtin(global_invocation_id) id: vec3u) {\n    if id.x >= params.size.x || id.y >= params.size.y {\n        return;\n    }\n\n    let count = atomicLoad(&bins[id.y * params.size.x + id.x]);\n    atomicMax(&maximum, count);\n    textureStore(target_texture, vec2i(id.xy), vec4f(f32(count), 0.0, 0.0, 1.0));\n}\n";

export const flatWgsl = "// Solid triangles with per-vertex color. Positions are pixels relative to the top left of the target.\n\nstruct Params {\n    target_size: vec2f,\n    width: f32,\n    color: vec4f,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n\nstruct VertexOutput {\n    @builtin(position) position: vec4f,\n    @location(0) color: vec4f,\n}\n\n@vertex\nfn vs_main(@location(0) position: vec2f, @location(1) color: vec4f) -> VertexOutput {\n    var output: VertexOutput;\n    let ndc = position / params.target_size * 2.0 - 1.0;\n    output.position = vec4f(ndc.x, -ndc.y, 0.0, 1.0);\n    output.color = color;\n    return output;\n}\n\n@fragment\nfn fs_main(input: VertexOutput) -> @location(0) vec4f {\n    return input.color;\n}\n";

export const imageWgsl = "// A texture on a rectangle. The rectangle comes from the uniforms, so that no vertex buffer is needed.\n// textureLoad picks the nearest texel, like the Skia backend, so that both show the same pixels.\n\nstruct Params {\n    target_size: vec2f,\n    width: f32,\n    color: vec4f,\n    scale: vec2f,\n    offset: vec2f,\n    // The fields of the other pipelines in between; the layout is shared.\n    unused_a: vec4f,\n    unused_b: vec4f,\n    unused_c: vec4f,\n    unused_d: vec4f,\n    unused_e: vec4f,\n    turn: vec4f,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n\n// A quarter turn clockwise for a chart whose X axis runs down: (x, y) lands at (sum - y, x).\nfn turned(point: vec2f) -> vec2f {\n    if (params.turn.x > 0.5) {\n        return vec2f(params.turn.y - point.y, point.x);\n    }\n\n    return point;\n}\n@group(1) @binding(0) var image: texture_2d<f32>;\n\nstruct VertexOutput {\n    @builtin(position) position: vec4f,\n    @location(0) uv: vec2f,\n}\n\n@vertex\nfn vs_main(@builtin(vertex_index) vertex_index: u32) -> VertexOutput {\n    var corners = array<vec2f, 6>(\n        vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0),\n        vec2f(0.0, 0.0), vec2f(1.0, 1.0), vec2f(0.0, 1.0),\n    );\n\n    let corner = corners[vertex_index];\n    let position = params.offset + params.scale * corner;\n    let ndc = turned(position) / params.target_size * 2.0 - 1.0;\n\n    var output: VertexOutput;\n    output.position = vec4f(ndc.x, -ndc.y, 0.0, 1.0);\n    output.uv = corner;\n    return output;\n}\n\n@fragment\nfn fs_main(input: VertexOutput) -> @location(0) vec4f {\n    let size = vec2i(textureDimensions(image));\n    let texel = clamp(vec2i(input.uv * vec2f(size)), vec2i(0), size - 1);\n    return textureLoad(image, texel, 0);\n}\n";

export const markerWgsl = "// One instanced quad per scatter point. Shapes and their inward borders are analytic signed\n// distance fields, so their edges stay smooth without MSAA.\n\nstruct Params {\n    target_size: vec2f,\n    border_width: f32,\n    border_color: vec4f,\n    scale: vec2f,\n    offset: vec2f,\n    size_scale: f32,\n    shape: u32,\n    // The fields of the other pipelines in between; the layout is shared.\n    unused_a: vec4f,\n    unused_b: vec4f,\n    unused_c: vec4f,\n    unused_d: vec4f,\n    turn: vec4f,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n\n// A quarter turn clockwise for a chart whose X axis runs down: (x, y) lands at (sum - y, x).\nfn turned(point: vec2f) -> vec2f {\n    if (params.turn.x > 0.5) {\n        return vec2f(params.turn.y - point.y, point.x);\n    }\n\n    return point;\n}\n\nstruct VertexOutput {\n    @builtin(position) position: vec4f,\n    @location(0) local: vec2f,\n    @location(1) color: vec4f,\n    @location(2) @interpolate(flat) half_size: f32,\n}\n\n@vertex\nfn vs_main(\n    @builtin(vertex_index) vertex_index: u32,\n    @location(0) marker_position: vec2f,\n    @location(1) marker_size: f32,\n    @location(2) color: vec4f,\n) -> VertexOutput {\n    var corners = array<vec2f, 6>(\n        vec2f(-1.0, -1.0), vec2f(1.0, -1.0), vec2f(1.0, 1.0),\n        vec2f(-1.0, -1.0), vec2f(1.0, 1.0), vec2f(-1.0, 1.0),\n    );\n\n    let half_size = marker_size * params.size_scale * 0.5;\n    let local = corners[vertex_index];\n    let pixel = marker_position * params.scale + params.offset + local * (half_size + 1.0);\n    let ndc = turned(pixel) / params.target_size * 2.0 - 1.0;\n\n    var output: VertexOutput;\n    output.position = vec4f(ndc.x, -ndc.y, 0.0, 1.0);\n    output.local = local * (1.0 + 1.0 / max(half_size, 0.001));\n    output.color = color;\n    output.half_size = half_size;\n    return output;\n}\n\nfn box_distance(point: vec2f, half_extent: vec2f) -> f32 {\n    let delta = abs(point) - half_extent;\n    return length(max(delta, vec2f(0.0))) + min(max(delta.x, delta.y), 0.0);\n}\n\nfn plus_distance(point: vec2f) -> f32 {\n    return min(box_distance(point, vec2f(0.34, 1.0)), box_distance(point, vec2f(1.0, 0.34)));\n}\n\nfn triangle_distance(value: vec2f) -> f32 {\n    let root_three = 1.7320508;\n    var point = vec2f(abs(value.x) - 1.0, value.y + 0.57735027);\n    if (point.x + root_three * point.y > 0.0) {\n        point = vec2f(point.x - root_three * point.y, -root_three * point.x - point.y) * 0.5;\n    }\n    point.x = point.x - clamp(point.x, -2.0, 0.0);\n    return -length(point) * sign(point.y);\n}\n\nfn shape_distance(point: vec2f) -> f32 {\n    switch params.shape {\n        case 0u: { return length(point) - 1.0; }\n        case 1u: { return box_distance(point, vec2f(1.0)); }\n        case 2u: { return triangle_distance(vec2f(point.x, -point.y)); }\n        case 3u: { return (abs(point.x) + abs(point.y) - 1.0) * 0.70710678; }\n        case 4u: {\n            let rotated = vec2f(point.x + point.y, point.y - point.x) * 0.70710678;\n            return plus_distance(rotated);\n        }\n        default: { return plus_distance(point); }\n    }\n}\n\n@fragment\nfn fs_main(input: VertexOutput) -> @location(0) vec4f {\n    if (input.half_size <= 0.0) {\n        discard;\n    }\n\n    let distance_pixels = shape_distance(input.local) * input.half_size;\n    let outer_coverage = clamp(0.5 - distance_pixels, 0.0, 1.0);\n    let fill_coverage = clamp(0.5 - distance_pixels - params.border_width, 0.0, 1.0);\n    let border_coverage = outer_coverage - fill_coverage;\n    let alpha = input.color.a * fill_coverage + params.border_color.a * border_coverage;\n    let rgb = select(\n        vec3f(0.0),\n        (input.color.rgb * input.color.a * fill_coverage\n            + params.border_color.rgb * params.border_color.a * border_coverage) / alpha,\n        alpha > 0.0,\n    );\n    return vec4f(rgb, alpha);\n}\n";

export const polylineWgsl = "// One instanced quad per line segment. The fragment shader computes the distance to the segment,\n// which gives analytic anti-aliasing and round joins and caps without MSAA.\n\nstruct Params {\n    target_size: vec2f,\n    width: f32,\n    color: vec4f,\n    scale: vec2f,\n    offset: vec2f,\n    glow_radius: f32,\n    glow_intensity: f32,\n    // The fields of the other pipelines in between; the layout is shared.\n    unused_a: vec4f,\n    unused_b: vec4f,\n    unused_c: vec4f,\n    unused_d: vec4f,\n    turn: vec4f,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n\n// A quarter turn clockwise for a chart whose X axis runs down: (x, y) lands at (sum - y, x).\nfn turned(point: vec2f) -> vec2f {\n    if (params.turn.x > 0.5) {\n        return vec2f(params.turn.y - point.y, point.x);\n    }\n\n    return point;\n}\n\nstruct VertexOutput {\n    @builtin(position) position: vec4f,\n    // Position in the segment frame: x along the segment from its start, y across it.\n    @location(0) local: vec2f,\n    @location(1) @interpolate(flat) segment_length: f32,\n}\n\n// Lines below one pixel render one pixel wide with reduced coverage.\nfn half_width() -> f32 {\n    return max(params.width, 1.0) * 0.5;\n}\n\n@vertex\nfn vs_main(\n    @builtin(vertex_index) vertex_index: u32,\n    @location(0) start: vec2f,\n    @location(1) end: vec2f,\n) -> VertexOutput {\n    var corners = array<vec2f, 6>(\n        vec2f(0.0, -1.0), vec2f(1.0, -1.0), vec2f(1.0, 1.0),\n        vec2f(0.0, -1.0), vec2f(1.0, 1.0), vec2f(0.0, 1.0),\n    );\n\n    // A gap point interrupts the line. All corners collapse, so the quad covers nothing.\n    if (start.x >= 1e30 || end.x >= 1e30) {\n        var hidden: VertexOutput;\n        hidden.position = vec4f(0.0, 0.0, 0.0, 1.0);\n        hidden.local = vec2f(0.0);\n        hidden.segment_length = 0.0;\n        return hidden;\n    }\n\n    let first = start * params.scale + params.offset;\n    let segment = (end - start) * params.scale;\n    let segment_length = length(segment);\n    let direction = select(vec2f(1.0, 0.0), segment / segment_length, segment_length > 0.0);\n    let normal = vec2f(-direction.y, direction.x);\n\n    // One extra pixel leaves room for the anti-aliased edge and the round caps.\n    let extent = half_width() + 1.0 + params.glow_radius;\n    let corner = corners[vertex_index];\n    let along = corner.x * (segment_length + 2.0 * extent) - extent;\n    let across = corner.y * extent;\n\n    let position = first + direction * along + normal * across;\n    let ndc = turned(position) / params.target_size * 2.0 - 1.0;\n\n    var output: VertexOutput;\n    output.position = vec4f(ndc.x, -ndc.y, 0.0, 1.0);\n    output.local = vec2f(along, across);\n    output.segment_length = segment_length;\n    return output;\n}\n\nfn segment_distance(input: VertexOutput) -> f32 {\n    let nearest = clamp(input.local.x, 0.0, input.segment_length);\n    return length(vec2f(input.local.x - nearest, input.local.y));\n}\n\n// Drawn with a maximum blend: neighboring segments overlap, and their glow must not add up.\n@fragment\nfn fs_glow(input: VertexOutput) -> @location(0) vec4f {\n    let reach = segment_distance(input) / params.glow_radius;\n    let alpha = params.color.a * params.glow_intensity * exp(-2.0 * reach * reach);\n    return vec4f(params.color.rgb * alpha, alpha);\n}\n\n@fragment\nfn fs_main(input: VertexOutput) -> @location(0) vec4f {\n    let distance = segment_distance(input);\n    let coverage = clamp(half_width() + 0.5 - distance, 0.0, 1.0) * min(params.width, 1.0);\n    return vec4f(params.color.rgb, params.color.a * coverage);\n}\n";

export const rasterWgsl = "// A texture of values on a rectangle, colored by a table. Changing the colors only needs another table.\n// textureLoad picks the nearest texel, like the Skia backend, so that both show the same pixels.\n\nstruct Params {\n    target_size: vec2f,\n    is_interpolated: f32,\n    // x: 0 nearest, 1 mean, 2 maximum.\n    reduction: vec4f,\n    scale: vec2f,\n    offset: vec2f,\n    is_log: f32,\n    row_shift: u32,\n    value_min: f32,\n    value_max: f32,\n    section_origin: vec2f,\n    section_size: vec2f,\n    missing_color: vec4f,\n    // A negative alpha stands for the end of the table.\n    below_color: vec4f,\n    above_color: vec4f,\n    turn: vec4f,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n\n// A quarter turn clockwise for a chart whose X axis runs down: (x, y) lands at (sum - y, x).\nfn turned(point: vec2f) -> vec2f {\n    if (params.turn.x > 0.5) {\n        return vec2f(params.turn.y - point.y, point.x);\n    }\n\n    return point;\n}\n@group(1) @binding(0) var values: texture_2d<f32>;\n@group(2) @binding(0) var colormap: texture_2d<f32>;\n\nstruct VertexOutput {\n    @builtin(position) position: vec4f,\n    @location(0) section: vec2f,\n}\n\n@vertex\nfn vs_main(@builtin(vertex_index) vertex_index: u32) -> VertexOutput {\n    var corners = array<vec2f, 6>(\n        vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0),\n        vec2f(0.0, 0.0), vec2f(1.0, 1.0), vec2f(0.0, 1.0),\n    );\n\n    let corner = corners[vertex_index];\n    let position = params.offset + params.scale * corner;\n    let ndc = turned(position) / params.target_size * 2.0 - 1.0;\n\n    var output: VertexOutput;\n    output.position = vec4f(ndc.x, -ndc.y, 0.0, 1.0);\n    output.section = params.section_origin + params.section_size * corner;\n    return output;\n}\n\nfn table_color(position: f32) -> vec4f {\n    let last = i32(textureDimensions(colormap).x) - 1;\n    let index = clamp(i32(floor(position * f32(last) + 0.5)), 0, last);\n    return textureLoad(colormap, vec2i(index, 0), 0);\n}\n\nfn load_value(position: vec2i, size: vec2i) -> f32 {\n    var texel = clamp(position, vec2i(0), size - 1);\n    texel.y = i32((u32(texel.y) + params.row_shift) % u32(size.y));\n    return textureLoad(values, texel, 0).r;\n}\n\n// A comparison could be optimized away, because shaders may assume that there is no NaN.\nfn is_nan(value: f32) -> bool {\n    return (bitcast<u32>(value) & 0x7fffffffu) > 0x7f800000u;\n}\n\n// Reads up to this many texels per direction, spread over the pixel.\nconst max_samples = 8;\n\nfn reduce_value(section: vec2f, size: vec2i) -> f32 {\n    let footprint = abs(params.section_size) * vec2f(size) / params.scale;\n    let samples = clamp(vec2i(ceil(footprint)), vec2i(1), vec2i(max_samples));\n    let start = section * vec2f(size) - footprint * 0.5;\n    let spacing = footprint / vec2f(samples);\n    var sum = 0.0;\n    var highest = 0.0;\n    var found = 0;\n    for (var y = 0; y < samples.y; y++) {\n        for (var x = 0; x < samples.x; x++) {\n            let position = start + (vec2f(f32(x), f32(y)) + 0.5) * spacing;\n            let value = load_value(vec2i(floor(position)), size);\n            if !is_nan(value) {\n                highest = select(max(highest, value), value, found == 0);\n                sum += value;\n                found += 1;\n            }\n        }\n    }\n\n    if found == 0 {\n        var nan_bits = 0x7fc00000u;\n        return bitcast<f32>(nan_bits);\n    }\n\n    return select(sum / f32(found), highest, params.reduction.x > 1.5);\n}\n\n@fragment\nfn fs_main(input: VertexOutput) -> @location(0) vec4f {\n    let size = vec2i(textureDimensions(values));\n    var value = 0.0;\n    if params.is_interpolated > 0.5 {\n        let position = input.section * vec2f(size) - 0.5;\n        let cell = vec2i(floor(position));\n        let part = position - floor(position);\n        let a = load_value(cell, size);\n        let b = load_value(cell + vec2i(1, 0), size);\n        let c = load_value(cell + vec2i(0, 1), size);\n        let d = load_value(cell + vec2i(1, 1), size);\n        if is_nan(a) || is_nan(b) || is_nan(c) || is_nan(d) {\n            return params.missing_color;\n        }\n\n        value = mix(mix(a, b, part.x), mix(c, d, part.x), part.y);\n    } else {\n        value = select(load_value(vec2i(floor(input.section * vec2f(size))), size), reduce_value(input.section, size), params.reduction.x > 0.5);\n        if is_nan(value) {\n            return params.missing_color;\n        }\n    }\n\n    if value < params.value_min || (params.is_log > 0.5 && value <= 0.0) {\n        return select(table_color(0.0), params.below_color, params.below_color.a >= 0.0);\n    }\n\n    if value > params.value_max {\n        return select(table_color(1.0), params.above_color, params.above_color.a >= 0.0);\n    }\n\n    var position = (value - params.value_min) / (params.value_max - params.value_min);\n    if params.is_log > 0.5 {\n        position = log(value / params.value_min) / log(params.value_max / params.value_min);\n    }\n\n    return table_color(position);\n}\n";

export const textWgsl = "// Instanced glyph quads, sampled from a multi-channel signed distance field. The median of the\n// channels restores sharp corners that a single distance channel would round off.\n\nstruct Params {\n    target_size: vec2f,\n    width: f32,\n    color: vec4f,\n}\n\n@group(0) @binding(0) var<uniform> params: Params;\n@group(1) @binding(0) var atlas: texture_2d<f32>;\n\nstruct VertexOutput {\n    @builtin(position) position: vec4f,\n    @location(0) uv: vec2f,\n    @location(1) color: vec4f,\n    @location(2) @interpolate(flat) distance_scale: f32,\n}\n\n@vertex\nfn vs_main(\n    @builtin(vertex_index) vertex_index: u32,\n    @location(0) glyph_position: vec2f,\n    @location(1) glyph_size: vec2f,\n    @location(2) uv_min: vec2f,\n    @location(3) uv_max: vec2f,\n    @location(4) color: vec4f,\n    @location(5) distance_scale: f32,\n    @location(6) rotation: f32,\n    @location(7) pivot: vec2f,\n) -> VertexOutput {\n    var corners = array<vec2f, 6>(\n        vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0),\n        vec2f(0.0, 0.0), vec2f(1.0, 1.0), vec2f(0.0, 1.0),\n    );\n\n    let corner = corners[vertex_index];\n    let offset = glyph_position + glyph_size * corner - pivot;\n    let turn = vec2f(cos(rotation), sin(rotation));\n    let position = pivot + vec2f(offset.x * turn.x - offset.y * turn.y, offset.x * turn.y + offset.y * turn.x);\n    let ndc = position / params.target_size * 2.0 - 1.0;\n\n    var output: VertexOutput;\n    output.position = vec4f(ndc.x, -ndc.y, 0.0, 1.0);\n    output.uv = uv_min + (uv_max - uv_min) * corner;\n    output.color = color;\n    output.distance_scale = distance_scale;\n    return output;\n}\n\nfn median(a: f32, b: f32, c: f32) -> f32 {\n    return max(min(a, b), min(max(a, b), c));\n}\n\n// Bilinear in the shader: hardware filters differ in precision and the field amplifies every difference.\nfn sample_atlas(uv: vec2f) -> vec3f {\n    let size = vec2i(textureDimensions(atlas));\n    let position = uv * vec2f(size) - 0.5;\n    let base = clamp(vec2i(floor(position)), vec2i(0), size - 1);\n    let next = min(base + 1, size - 1);\n    let weight = clamp(position - vec2f(base), vec2f(0.0), vec2f(1.0));\n\n    let upper = mix(\n        textureLoad(atlas, base, 0).rgb,\n        textureLoad(atlas, vec2i(next.x, base.y), 0).rgb,\n        weight.x);\n    let lower = mix(\n        textureLoad(atlas, vec2i(base.x, next.y), 0).rgb,\n        textureLoad(atlas, next, 0).rgb,\n        weight.x);\n    return mix(upper, lower, weight.y);\n}\n\n// Small text gets slightly stronger strokes: a stroke of one pixel or less that falls between two pixels would\n// otherwise show as two faint columns. The em size in pixels is the distance scale times 40 / (2 * 4), the em size\n// and range of the field. The same rule is in the glyph rasterizer of the software renderer.\nfn embolden(distance_scale: f32) -> f32 {\n    let em_pixels = distance_scale * 5.0;\n    return clamp((16.0 - em_pixels) / 8.0, 0.0, 1.0) * 0.15;\n}\n\n@fragment\nfn fs_main(input: VertexOutput) -> @location(0) vec4f {\n    let distance = sample_atlas(input.uv);\n    let signed_distance = median(distance.r, distance.g, distance.b) - 0.5;\n    let coverage = clamp(signed_distance * input.distance_scale + 0.5 + embolden(input.distance_scale), 0.0, 1.0);\n    return vec4f(input.color.rgb, input.color.a * coverage);\n}\n";
